namespace Videira {public partial class VideiraSite {
 void SettingsPage(){var root=PageRoot("Configurações do site");var tabs=new TabControl{Height=500,Padding=new Point(18,9),Margin=Padding.Empty};var inputs=new Dictionary<string,TextBox>();Func<TabPage,int,TableLayoutPanel> group=(page,count)=>Fields(page,count);Action<TableLayoutPanel,string,string,bool> input=(form,key,label,multi)=>{var textbox=Field(form,label,SiteApi.Read(storeSettings,key),multi);textbox.MaxLength=multi?3000:2000;inputs[key]=textbox;};
 var general=group(Tab(tabs,"Geral"),7);input(general,"store_name","Nome da loja",false);input(general,"tagline","Descrição curta / slogan",false);input(general,"whatsapp","WhatsApp com país e DDD",false);input(general,"contact_email","E-mail de contato público",false);input(general,"instagram_url","Instagram — URL HTTPS",false);input(general,"address","Endereço",false);input(general,"opening_hours","Horário de atendimento",false);
 var look=group(Tab(tabs,"Aparência"),6);input(look,"logo_url","Logo — URL HTTPS (vazio: logo atual)",false);input(look,"primary_color","Cor principal — hexadecimal, ex.: #73233a",false);input(look,"announcement","Mensagem de destaque (vazio: ocultar)",false);input(look,"featured_title","Título da seleção na página inicial",false);look.RowStyles[4].Height=150;input(look,"footer_text","Texto do rodapé",true);var selectColor=ActionButton("Escolher cor",()=>{using(var d=new ColorDialog()){try{d.Color=ColorTranslator.FromHtml(inputs["primary_color"].Text);}catch{}if(d.ShowDialog(this)==DialogResult.OK)inputs["primary_color"].Text=ColorTranslator.ToHtml(d.Color);}return Task.FromResult(0);});look.Controls.Add(selectColor);
 var home=group(Tab(tabs,"Página inicial"),5);input(home,"hero_title","Título do primeiro banner",false);home.RowStyles[1].Height=150;input(home,"hero_text","Texto do primeiro banner",true);input(home,"hero_image_url","Imagem do banner — URL HTTPS (vazio: imagem atual)",false);input(home,"hero_link_label","Texto do botão do banner",false);input(home,"hero_link_url","Destino do botão — /loja ou URL HTTPS",false);
 var payment=group(Tab(tabs,"Pagamento"),5);var show=new CheckBox{Text="Mostrar preços no catálogo",Checked=!storeSettings.ContainsKey("show_prices")||Flag(storeSettings,"show_prices"),Dock=DockStyle.Fill};payment.Controls.Add(show);var installments=new NumericUpDown{Minimum=1,Maximum=12,Value=storeSettings.ContainsKey("card_installments")?Convert.ToDecimal(storeSettings["card_installments"]):1,Dock=DockStyle.Top};var wrap=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=2};wrap.RowStyles.Add(new RowStyle(SizeType.Absolute,25));wrap.Controls.Add(new Label{Text="Máximo de parcelas no cartão",Dock=DockStyle.Fill});wrap.Controls.Add(installments);payment.Controls.Add(wrap);input(payment,"card_min_installment","Valor mínimo de cada parcela (R$) — opcional",false);var interest=new CheckBox{Text="Parcelamento sem juros",Checked=Flag(storeSettings,"card_interest_free"),Dock=DockStyle.Fill};payment.Controls.Add(interest);payment.RowStyles[4].Height=150;input(payment,"payment_note","Orientação pública sobre pagamento",true);
 var seo=group(Tab(tabs,"SEO"),2);seo.RowStyles[0].Height=180;input(seo,"meta_description","Descrição para buscadores",true);seo.Controls.Add(Copy("O nome da loja compõe o título das páginas.\nA descrição é publicada no HTML do site.\nO e-mail de contato não altera a conta administradora.",90));
 var save=ActionButton("Salvar todas as configurações",async()=>{var data=inputs.ToDictionary(p=>p.Key,p=>(object)p.Value.Text.Trim());if((string)data["store_name"]=="")throw new Exception("Informe o nome da loja.");string phone=new string(((string)data["whatsapp"]).Where(Char.IsDigit).ToArray());if(phone.Length<12||phone.Length>15)throw new Exception("Informe o WhatsApp com país e DDD.");data["whatsapp"]=phone;foreach(string key in new[]{"logo_url","hero_image_url","instagram_url"})ValidateHttps((string)data[key],key);string color=(string)data["primary_color"];if(!System.Text.RegularExpressions.Regex.IsMatch(color,"^#[0-9a-fA-F]{6}$"))throw new Exception("Use uma cor hexadecimal com seis dígitos.");string link=(string)data["hero_link_url"];if(link!="/loja")ValidateHttps(link,"destino do botão");if(link=="")data["hero_link_url"]="/loja";string mail=(string)data["contact_email"];if(mail!=""){try{new System.Net.Mail.MailAddress(mail);}catch{throw new Exception("Informe um e-mail de contato válido.");}}object min=ReadMoney(inputs["card_min_installment"]);if(min!=null&&Convert.ToDecimal(min)<=0)throw new Exception("O valor mínimo da parcela deve ser maior que zero.");data["card_min_installment"]=min;data["card_installments"]=(int)installments.Value;data["card_interest_free"]=interest.Checked;data["show_prices"]=show.Checked;var rows=(object[])await api.Request("/rest/v1/store_settings?id=eq.true","PATCH",data);if(rows==null||rows.Length!=1)throw new Exception("O site não confirmou as configurações.");storeSettings=(Dictionary<string,object>)rows[0];dirty=false;Notify("Configurações publicadas no site. Atualize a página para conferir.");},true);var tools=Buttons();tools.Controls.Add(save);tools.Controls.Add(ActionButton("Ver site",()=>{System.Diagnostics.Process.Start("https://videira-loja.vercel.app/");return Task.FromResult(0);}));root.Controls.Add(tools);root.Controls.Add(tabs);show.CheckedChanged+=(s,e)=>dirty=true;interest.CheckedChanged+=(s,e)=>dirty=true;installments.ValueChanged+=(s,e)=>dirty=true;dirty=false;}
