 void SetShell(bool signedIn){var shell=sidebar.Parent as TableLayoutPanel;if(shell!=null){shell.ColumnStyles[0].Width=signedIn?190:0;shell.RowStyles[0].Height=signedIn?36:0;}sidebar.Visible=signedIn;}
 void LoginPage(){SetShell(false);currentRoot=null;foreach(Control c in body.Controls.Cast<Control>().ToArray()){body.Controls.Remove(c);c.Dispose();}loginCard=new Panel{Width=460,Height=490,BackColor=Color.White,BorderStyle=BorderStyle.FixedSingle};body.Controls.Add(loginCard);loginCard.Controls.Add(new Label{Text="V",Font=new Font("Georgia",38,FontStyle.Bold),ForeColor=blue,TextAlign=ContentAlignment.MiddleCenter,Location=new Point(20,20),Size=new Size(420,70)});loginCard.Controls.Add(new Label{Text="VIDEIRA  •  PAINEL DO SITE",Font=new Font("Segoe UI",13,FontStyle.Bold),TextAlign=ContentAlignment.MiddleCenter,Location=new Point(20,90),Size=new Size(420,40)});loginCard.Controls.Add(new Label{Text="E-mail do administrador",Location=new Point(35,151),AutoSize=true});var email=new TextBox{Text=SiteApi.AdminEmail,ReadOnly=true,Location=new Point(35,181),Width=388};loginCard.Controls.Add(email);loginCard.Controls.Add(new Label{Text="Senha",Location=new Point(35,229),AutoSize=true});var pass=new TextBox{UseSystemPasswordChar=true,Location=new Point(35,260),Width=388};loginCard.Controls.Add(pass);var show=new CheckBox{Text="Mostrar senha",Location=new Point(35,302),AutoSize=true};show.CheckedChanged+=(s,e)=>pass.UseSystemPasswordChar=!show.Checked;loginCard.Controls.Add(show);var enter=ActionButton("Acessar",async()=>{await api.Login(SiteApi.AdminEmail,pass.Text);pass.Clear();await Reload();account.Text="Conectado • "+SiteApi.AdminEmail;ShowPage("Painel");Notify("Conectado ao catálogo online.");},true);enter.Location=new Point(35,352);loginCard.Controls.Add(enter);var recover=ActionButton("Recuperar acesso",()=>{RecoveryDialog();return Task.FromResult(0);});recover.Location=new Point(170,352);loginCard.Controls.Add(recover);loginCard.Controls.Add(new Label{Text="Administre produtos, categorias e configurações da loja.",Location=new Point(35,422),Size=new Size(390,45),ForeColor=Color.DimGray,TextAlign=ContentAlignment.MiddleCenter});pass.KeyDown+=(s,e)=>{if(e.KeyCode==Keys.Enter){e.SuppressKeyPress=true;enter.PerformClick();}};FitPage();dirty=false;}
